  font-weight: 650;
  letter-spacing: -0.015em;
}
@media (prefers-reduced-motion: no-preference) {
  .root:not([data-reduced]) .art {
    transition:
      translate var(--mk-duration-slow, 560ms) var(--mk-ease-emphasized, ease),
      box-shadow var(--mk-duration-slow, 560ms) var(--mk-ease-emphasized, ease);
  }
  .root:not([data-reduced]) .art svg { transition: transform var(--mk-duration-slow, 560ms) var(--mk-ease-emphasized, ease); }
}
@media (hover: hover) {
  .root:not([data-reduced]) .card:hover .art {
    translate: 0 -3px;
    box-shadow: 0 1px 1px rgb(0 0 0 / 0.04), 0 22px 36px -20px rgb(0 0 0 / 0.5);
  }
  .root:not([data-reduced]) .card:hover .art svg { transform: scale(1.045); }
  .card:hover .title { text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 0.2em; }
}

/* ── Archive strip ───────────────────────────────────────────────────────── */
.archive { timeline-scope: --cf-archive; }
.frame {
  position: relative;
  overflow: clip;
  border-radius: var(--mk-radius-m, 10px);
}
.frame:has(.strip:focus-visible) { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 4px; }
.strip {
  position: relative;
  overflow-x: auto;
  overflow-y: hidden;
  overscroll-behavior-x: contain;
  scrollbar-width: none;
  scroll-timeline: --cf-archive x;
  outline: none;
  cursor: grab;
}
.strip::-webkit-scrollbar { display: none; }
.strip[data-dragging] { cursor: grabbing; user-select: none; }
.track {
  display: flex;
  gap: 0.75rem;
  width: max-content;
  margin: 0;
  padding: 0 3rem 0 0;
  list-style: none;
}
.tile {
  flex: none;
  display: grid;
  gap: 0.5rem;
  width: clamp(8.5rem, 20cqi, 11.25rem);
}
.tileArt {
  display: block;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  border-radius: var(--mk-radius-s, 4px);
  background: var(--mk-surface-2, #e9e5da);
}
.tileArt svg { display: block; width: 100%; height: 100%; }
.tileCap {
  display: grid;
  gap: 0.2rem;
  font-size: 0.8125rem;
  line-height: 1.3;
}
.tileTitle { font-weight: 550; }
.fade {
  position: absolute;
  inset: 0 0 0 auto;
  width: 3rem;
  pointer-events: none;
  background: linear-gradient(to left, var(--mk-surface, #fbf9f4), transparent);
}
.progress {
  position: relative;
  height: 2px;
  margin-top: 0.875rem;
  overflow: hidden;
  border-radius: 2px;
  background: var(--mk-line, #11110f24);
}
.progress span {
  position: absolute;
  inset: 0 auto 0 0;
  width: 24%;
  border-radius: inherit;
  background: var(--mk-ink, #11110f);
}
@supports (animation-timeline: scroll()) {
  .progress span { animation: progress linear both; animation-timeline: --cf-archive; }
}
@keyframes progress { to { transform: translateX(316.667%); } }

/* ── Footer ──────────────────────────────────────────────────────────────── */
.foot {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem 2rem;
  padding-top: 0.875rem;
  border-top: 1px solid var(--mk-line, #11110f24);
}
.hint {
  margin: 0;
  max-width: 64ch;
  font-size: 0.8125rem;
  line-height: 1.5;
  color: var(--mk-ink-muted, #5c5a52);
  text-wrap: pretty;
}
.status { margin: 0; min-height: 1.5em; color: var(--mk-ink, #11110f); text-transform: none; letter-spacing: 0.02em; }

/* ── Artwork paints (SVG classes; theme tokens, so both themes work) ─────── */
.fi { fill: var(--mk-ink, #11110f); }
.fs { fill: var(--mk-signal, #bf2f09); }
.fp { fill: var(--mk-surface, #fbf9f4); }
.fm { fill: var(--mk-ink-muted, #5c5a52); }
.si { fill: none; stroke: var(--mk-ink, #11110f); }
.ss { fill: none; stroke: var(--mk-signal, #bf2f09); }
.sp { fill: none; stroke: var(--mk-surface, #fbf9f4); }
.serif { font-family: var(--mk-font-serif, Georgia, serif); font-style: italic; }
.mono { font-family: var(--mk-font-mono, ui-monospace, monospace); font-weight: 600; }
